// Classified executor: policy per error class (plain JS)
const POLICIES = {
  transient: { retries: 3, backoffMs: [200, 800, 2000], then: "escalate" },
  auth: { retries: 0, then: "escalate-and-rotate" },
  invalid: { retries: 0, repair: 1, then: "quarantine" },
  downstream: { retries: 1, then: "fallback-cascade" },
  budget: { retries: 0, then: "escalate-with-trail" },
};
function classify(err) {
  if (err.status === 401 || err.status === 403) return "auth";
  if (err.status >= 500 || err.code === "TIMEOUT" || err.code === "RATE_LIMIT") return "transient";
  if (err.status === 400 || err.code === "SCHEMA") return "invalid";
  if (err.code === "DOWN") return "downstream";
  return "budget";
}
// Classification first, policy second — never catch-all, never blind retry.

