function classify(err) {
  if (err.status === 401 || err.status === 403) return 'auth';
  if (err.status >= 500 || err.code === 'TIMEOUT' || err.code === 'RATE_LIMIT') return 'transient';
  if (err.status === 400 || err.code === 'SCHEMA') return 'invalid';
  if (err.code === 'DOWN') return 'downstream';
  return 'budget';
}
const POLICIES = { transient: 'retry-backoff', auth: 'escalate-noretry', invalid: 'repair-once-quarantine', downstream: 'fallback', budget: 'escalate-trail' };
const cases = [
  [{ status: 503 }, 'transient'],
  [{ status: 401 }, 'auth'],
  [{ status: 400 }, 'invalid'],
  [{ code: 'TIMEOUT' }, 'transient'],
  [{ code: 'DOWN' }, 'downstream'],
  [{ code: 'UNKNOWN_WEIRD' }, 'budget'],
];
let pass = 0;
for (const [err, expected] of cases) {
  const got = classify(err);
  if (got === expected) pass++;
  else console.log('MISS ' + JSON.stringify(err) + ' -> ' + got);
}
console.log(pass + '/' + cases.length + ' errors classified');
console.log('auth policy: ' + POLICIES[classify({ status: 403 })]);

